    from math import gcd

    remainders = inputs['remainders']
    moduli = inputs['moduli']

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd_val, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd_val, x, y

    def crt_two(r1, m1, r2, m2):
        g, p, q = extended_gcd(m1, m2)
        if (r2 - r1) % g != 0:
            return None, None
        lcm = m1 * m2 // g
        x = (r1 + m1 * ((r2 - r1) // g) * p) % lcm
        return x, lcm

    x = remainders[0]
    mod = moduli[0]

    for i in range(1, len(remainders)):
        x, mod = crt_two(x, mod, remainders[i], moduli[i])
        if x is None:
            return -1

    return float(x % mod)

